demo=[[1,9,1,9],[9,9,9,1],[1,1,4,1],[9,4,1,9],[1,1,1,4]]
def transform(grid):
    out=[]
    for block in (grid[::-1], grid, grid[::-1]):
        for row in block:
            out.append(row[::-1]+row)
    return out
pred=transform(demo)
print('\n'.join(' '.join(map(str,r)) for r in pred))
